import{_ as r,C as n,o as a,c as i,aj as t,G as s}from"./chunks/framework.BwH0p-pt.js";const m=JSON.parse('{"title":"Webhooks","description":"","frontmatter":{},"headers":[],"relativePath":"2.1/configuration/webhooks.md","filePath":"2.1/configuration/webhooks.md","lastUpdated":1788942616000}'),d={name:"2.1/configuration/webhooks.md"};function h(l,e,c,u,p,g){const o=n("ImagePopup");return a(),i("div",null,[e[0]||(e[0]=t('<h1 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h1><p>Webhooks in <a href="https://unopim.com/" target="_blank" rel="noreferrer">UnoPim</a> let you push real-time product update notifications to an external URL whenever product data changes. Instead of polling the API, your connected systems (e-commerce storefronts, ERPs, marketplaces) receive an HTTP request the moment a product is created, updated, or deleted.</p><p>The Webhook Settings page is located at <strong>Configuration → Webhooks</strong> in the admin sidebar.</p><div class="tip custom-block"><p class="custom-block-title">Async dispatch</p><p>Webhook deliveries now run in the background as a queued <strong><code>SendProductWebhook</code></strong> job. On product create and update, the <code>Product</code> listener dispatches the job to the <strong><code>webhooks</code></strong> queue (<code>-&gt;onQueue(&#39;webhooks&#39;)</code>). Admin save actions return immediately — a slow receiving endpoint can no longer block the UI. Webhook log entries are still recorded once the job completes; the <code>webhook_logs.user_id</code> column is now nullable to support system-dispatched deliveries.</p></div><h2 id="running-the-queue-worker" tabindex="-1">Running the queue worker <a class="header-anchor" href="#running-the-queue-worker" aria-label="Permalink to &quot;Running the queue worker&quot;">​</a></h2><p>Because webhook deliveries are queued on the <strong><code>webhooks</code></strong> queue, a plain <code>php artisan queue:work</code> will <strong>not</strong> drain them — you have to include <code>webhooks</code> in the <code>--queue</code> list. Most UnoPim installations run a single worker that pulls from every queue the platform uses:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --queue=webhooks,system,default,completeness</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Queue</th><th>Used by</th></tr></thead><tbody><tr><td><strong><code>webhooks</code></strong></td><td><code>SendProductWebhook</code> job — product create/update notifications.</td></tr><tr><td><strong><code>system</code></strong></td><td>System-level jobs such as translation queues and indexing.</td></tr><tr><td><strong><code>default</code></strong></td><td>Laravel&#39;s default queue — anything dispatched without an explicit queue.</td></tr><tr><td><strong><code>completeness</code></strong></td><td><code>BulkProductCompletenessJob</code> and per-product completeness recalculation.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If you run <code>php artisan queue:work</code> without <code>--queue=webhooks,...</code>, webhook deliveries will sit in the queue forever and the <strong>Logs</strong> tab will appear empty even though admin saves look successful. Always include <code>webhooks</code> in the queue list (or run a dedicated worker just for <code>webhooks</code>).</p></div><div class="tip custom-block"><p class="custom-block-title">Supervisor / systemd</p><p>In production, supervise this command with Supervisor or systemd so the worker restarts automatically on failure. Run <code>php artisan queue:restart</code> after every deploy so workers pick up your latest code.</p></div><h2 id="retry-policy" tabindex="-1">Retry policy <a class="header-anchor" href="#retry-policy" aria-label="Permalink to &quot;Retry policy&quot;">​</a></h2><p>If your receiving endpoint is down or returns an error, UnoPim does <strong>not</strong> give up after the first attempt. The <code>SendProductWebhook</code> job has a built-in retry policy:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Value</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Tries</strong></td><td><code>3</code></td><td>UnoPim attempts each webhook up to <strong>three times</strong> before marking it failed.</td></tr><tr><td><strong>Backoff</strong></td><td><code>30 seconds</code></td><td>After a failed attempt, UnoPim waits <strong>30 seconds</strong> before retrying.</td></tr></tbody></table><p>So in the worst case, a single product save can produce up to <strong>three</strong> delivery attempts spread across roughly a minute. Each attempt records a row in the <strong>Logs</strong> tab so you can see exactly what happened — success on attempt 1 is one log row, two failures plus a success on attempt 3 is three log rows.</p><div class="tip custom-block"><p class="custom-block-title">Make your endpoint idempotent</p><p>Because the same payload may arrive more than once (e.g. attempt #1 timed out but actually succeeded server-side), build your receiving endpoint so that processing the <strong>same event twice produces the same result</strong>. A common pattern is to dedupe on the <code>event_id</code> field of the incoming JSON.</p></div><div class="warning custom-block"><p class="custom-block-title">Worker must be running for retries</p><p>The retry logic only fires when a queue worker is actively pulling from the <code>webhooks</code> queue. If you stop the worker, retries pause until you restart it — they don&#39;t expire.</p></div><h2 id="general-tab" tabindex="-1">General Tab <a class="header-anchor" href="#general-tab" aria-label="Permalink to &quot;General Tab&quot;">​</a></h2><p>The <strong>General</strong> tab is where you enable the webhook and configure the destination URL. It uses a two-panel layout.</p>',18)),s(o,{src:"/assets/2.1/images/settings/webhook-settings.png",alt:"Webhook Settings"}),e[1]||(e[1]=t('<h3 id="enable-the-webhook-and-set-the-url" tabindex="-1">Enable the Webhook and Set the URL <a class="header-anchor" href="#enable-the-webhook-and-set-the-url" aria-label="Permalink to &quot;Enable the Webhook and Set the URL&quot;">​</a></h3><p><strong>Step 1:</strong> Navigate to <strong>Configuration → Webhooks</strong> in the admin sidebar. The <strong>General</strong> tab is selected by default.</p><p><strong>Step 2:</strong> In the <strong>General</strong> panel on the left, toggle <strong>Active Webhook</strong> to enable webhook delivery.</p><p><strong>Step 3:</strong> In the <strong>Settings</strong> panel on the right, enter your <strong>Webhook URL</strong> (e.g., <code>https://example.com/webhook</code>). This is the endpoint that will receive POST requests whenever product data changes.</p><p><strong>Step 4:</strong> Click the <strong>Save</strong> button at the top-right of the page to apply your configuration.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use a service like <a href="https://webhook.site" target="_blank" rel="noreferrer">webhook.site</a> during development to inspect the payloads UnoPim sends before building your processing logic.</p></div><h2 id="logs-tab" tabindex="-1">Logs Tab <a class="header-anchor" href="#logs-tab" aria-label="Permalink to &quot;Logs Tab&quot;">​</a></h2><p>The <strong>Logs</strong> tab displays a record of every webhook request that UnoPim has sent. Use it to monitor delivery status and troubleshoot failures.</p>',8)),s(o,{src:"/assets/2.1/images/settings/webhook-logs.png",alt:"Webhook Logs"}),e[2]||(e[2]=t('<p>The log datagrid includes the following columns:</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Id</strong></td><td>Unique identifier for the log entry</td></tr><tr><td><strong>Date/Time</strong></td><td>When the webhook request was sent</td></tr><tr><td><strong>SKU</strong></td><td>The product SKU that triggered the webhook</td></tr><tr><td><strong>User</strong></td><td>The admin user whose action triggered the change</td></tr><tr><td><strong>Status</strong></td><td>The HTTP response status code returned by your endpoint</td></tr><tr><td><strong>Actions</strong></td><td>View details of the individual log entry</td></tr></tbody></table><p>You can use the <strong>search bar</strong> to search by code, the <strong>Filter</strong> button to narrow results, and the <strong>pagination</strong> controls to browse through entries.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you see non-200 status codes in the logs, check that your endpoint is reachable, returns a 200 OK response, and can handle the incoming JSON payload correctly.</p></div><h2 id="history-tab" tabindex="-1">History Tab <a class="header-anchor" href="#history-tab" aria-label="Permalink to &quot;History Tab&quot;">​</a></h2><p>The <strong>History</strong> tab tracks every change made to the webhook configuration itself. Use it to audit when settings were modified and by whom.</p>',6)),s(o,{src:"/assets/2.1/images/settings/webhook-history.png",alt:"Webhook History"}),e[3]||(e[3]=t('<p>The history datagrid includes the following columns:</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Date/Time</strong></td><td>When the configuration change was made</td></tr><tr><td><strong>Version</strong></td><td>The version number of the configuration snapshot</td></tr><tr><td><strong>User</strong></td><td>The admin user who made the change</td></tr><tr><td><strong>Actions</strong></td><td>Click the eye icon to view the full details of what changed</td></tr></tbody></table><p>This is useful for tracking when the webhook URL was updated, when the webhook was enabled or disabled, and which user made the change.</p><h2 id="quick-setup-summary" tabindex="-1">Quick Setup Summary <a class="header-anchor" href="#quick-setup-summary" aria-label="Permalink to &quot;Quick Setup Summary&quot;">​</a></h2><ol><li>Go to <strong>Configuration → Webhooks</strong>.</li><li>On the <strong>General</strong> tab, toggle <strong>Active Webhook</strong> on.</li><li>Enter your <strong>Webhook URL</strong> in the Settings panel.</li><li>Click <strong>Save</strong>.</li><li>Switch to the <strong>Logs</strong> tab to monitor outgoing webhook deliveries and verify successful responses.</li><li>Switch to the <strong>History</strong> tab to review any past configuration changes.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If your receiving endpoint is temporarily down, toggle the Active Webhook off to pause deliveries. Your configuration is preserved and you can re-enable it at any time without re-entering the URL.</p></div>',6))])}const k=r(d,[["render",h]]);export{m as __pageData,k as default};
